import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadJson } from "./util";

// One Discord application (bot) per agent is what gives each agent its own
// native identity in DMs *and* channels (webhooks only work in guild channels).
// A token is resolved per agent id, from an env override first, then a json file
// that the onboarding script writes to.

const TOKENS_FILE = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  ".data",
  "discord-tokens.json"
);

type TokenMap = Record<string, string>; // agentId -> bot token

const fileTokens: TokenMap = loadJson<TokenMap>(TOKENS_FILE, {});

/**
 * Env var that overrides the token file for an agent, e.g.
 * `accessbuddy/feature-dev` -> `DISCORD_TOKEN_ACCESSBUDDY_FEATURE_DEV`.
 */
export function tokenEnvVar(agentId: string): string {
  const suffix = agentId
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return `DISCORD_TOKEN_${suffix}`;
}

/** Resolve an agent's Discord bot token: env override first, then the token file. */
export function tokenForAgent(agentId: string): string | undefined {
  const env = process.env[tokenEnvVar(agentId)];
  if (env && env.trim()) return env.trim();
  const fromFile = fileTokens[agentId];
  return fromFile && fromFile.trim() ? fromFile.trim() : undefined;
}

export function hasToken(agentId: string): boolean {
  return Boolean(tokenForAgent(agentId));
}

import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadJson, saveJson } from "./util";

// ISC-7: persistent memory across messages. Each conversation surface (a DM with
// an agent, or the agent's own channel/thread) maps to a Claude Agent SDK
// session id. Resuming that session id replays the full prior conversation, so a
// thread is no longer one-off — it remembers.

const SESSIONS_FILE = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  ".data",
  "sessions.json"
);

interface SessionRec {
  sessionId: string;
  updatedAt: number;
}

type SessionStore = Record<string, SessionRec>;

const store: SessionStore = loadJson<SessionStore>(SESSIONS_FILE, {});

/** Conversation key for a DM with an agent — one resumable thread per (agent, user). */
export function dmKey(agentId: string, userId: string): string {
  return `dm:${agentId}:${userId}`;
}

/** Conversation key for an agent's channel (or a thread within it). */
export function channelKey(agentId: string, channelId: string, threadId?: string): string {
  return threadId
    ? `ch:${agentId}:${channelId}:${threadId}`
    : `ch:${agentId}:${channelId}`;
}

export function getSession(key: string): string | undefined {
  return store[key]?.sessionId;
}

export function setSession(key: string, sessionId: string): void {
  if (!sessionId) return;
  store[key] = { sessionId, updatedAt: Date.now() };
  saveJson(SESSIONS_FILE, store);
}

import { createSdkMcpServer, tool } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";
import fs from "node:fs";
import path from "node:path";

// ISC-8: gated memory growth. Every agent gets an `update_memory` tool that
// appends a durable note to its own memory.md. The tool is deliberately NOT in
// `allowedTools`, so `canUseTool` fires for it and Nick approves each write —
// the agent's definition is owned and grown by PAI, but only with sign-off.

export const MEMORY_TOOL_NAME = "mcp__memory__update_memory";

export function memoryServer(agentDir: string) {
  return createSdkMcpServer({
    name: "memory",
    version: "1.0.0",
    tools: [
      tool(
        "update_memory",
        "Append a durable note to your own memory.md so you remember it in future sessions. " +
          "Requires Nick's approval. Use for facts, preferences, and decisions worth keeping.",
        { note: z.string().describe("The note to remember (one or two sentences)") },
        async (args) => {
          const note = args.note.trim();
          const file = path.join(agentDir, "memory.md");
          const stamp = new Date().toISOString().slice(0, 10);
          fs.appendFileSync(file, `\n- (${stamp}) ${note}\n`);
          return {
            content: [{ type: "text" as const, text: `Saved to memory.md: ${note}` }],
          };
        }
      ),
    ],
  });
}

import { createSdkMcpServer, tool } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";

// ISC-9: free-form ask_user. Lets an agent pause mid-task to ask Nick a question
// and wait for his reply, rather than only the Approve/Deny gate. The frontend
// supplies `onAskUser`, which posts the question to the conversation and resolves
// with Nick's next message.

export type OnAskUser = (question: string) => Promise<string>;

export const ASK_USER_TOOL_NAME = "mcp__askuser__ask_user";

export function askUserServer(onAskUser: OnAskUser) {
  return createSdkMcpServer({
    name: "askuser",
    version: "1.0.0",
    tools: [
      tool(
        "ask_user",
        "Ask Nick a free-form question and wait for his reply. Use when you need information " +
          "or a decision only he can give. Returns his answer as text.",
        { question: z.string().describe("The question to ask Nick") },
        async (args) => {
          const answer = await onAskUser(args.question);
          return { content: [{ type: "text" as const, text: answer }] };
        }
      ),
    ],
  });
}

import { query, type Options } from "@anthropic-ai/claude-agent-sdk";
import { buildSystemPrompt, type Agent } from "./roster";
import { policyFor, summarizeTool } from "./agentConfig";
import { delegationAgents } from "./delegation";
import { delegateServer, DELEGATE_TOOL_NAME, type OnDelegate } from "./delegateTool";
import { askUserServer, ASK_USER_TOOL_NAME, type OnAskUser } from "./askUserTool";
import { memoryServer } from "./memoryTool";

export type TaskEvent =
  | { kind: "text"; text: string }
  | { kind: "tool"; tool: string; summary: string; delegated: boolean }
  | { kind: "result"; text: string; costUsd: number; turns: number }
  | { kind: "error"; message: string };

export interface RunOptions {
  agent: Agent;
  prompt: string;
  onEvent: (e: TaskEvent) => void | Promise<void>;
  canUseTool: Options["canUseTool"];
  controller?: AbortController;
  /** When set on an orchestrator, gives it a `delegate` tool that runs an agent in its own channel. */
  onDelegate?: OnDelegate;
  /** When set, gives the agent an `ask_user` tool that pauses for a free-form reply. */
  onAskUser?: OnAskUser;
  /** A prior SDK session id to resume (ISC-7) — replays the conversation so the thread remembers. */
  resume?: string;
}

/**
 * Run one agent task via the Claude Agent SDK, streaming tool/skill activity and
 * the final result through `onEvent`. Uses the Claude subscription (no API key).
 * Returns the (possibly new) session id so the caller can persist it for resume.
 */
export async function runAgentTask(
  opts: RunOptions
): Promise<{ result: string; costUsd: number; sessionId: string }> {
  const { agent, prompt, onEvent, canUseTool, controller, onDelegate, onAskUser, resume } = opts;
  const policy = policyFor(agent);

  // Orchestrator + a channel-aware onDelegate → give it the custom `delegate` tool
  // (runs the target agent in its own channel). Otherwise fall back to native subagents.
  const useChannelDelegate = policy.isOrchestrator && Boolean(onDelegate);

  // Every agent can propose memory updates (gated — `update_memory` is intentionally
  // NOT in allowedTools, so canUseTool routes it to approval).
  const mcpServers: NonNullable<Options["mcpServers"]> = {
    memory: memoryServer(agent.dir),
  };
  if (useChannelDelegate) mcpServers.delegation = delegateServer(agent.id, onDelegate!);
  if (onAskUser) mcpServers.askuser = askUserServer(onAskUser);

  const extraAllowed = [
    ...(useChannelDelegate ? [DELEGATE_TOOL_NAME] : []),
    ...(onAskUser ? [ASK_USER_TOOL_NAME] : []),
  ];

  const options: Options = {
    cwd: policy.cwd,
    systemPrompt: { type: "preset", preset: "claude_code", append: buildSystemPrompt(agent) },
    allowedTools: [...policy.allowedTools, ...extraAllowed],
    canUseTool,
    permissionMode: "default",
    settingSources: [], // don't load the user's PAI settings/hooks into spawned sessions
    maxTurns: Number(process.env.MAX_TURNS ?? 24),
    model: process.env.AGENT_MODEL || undefined,
    abortController: controller,
    // Subscription auth (strip API key) + avoid the nested-session guard (strip CLAUDECODE).
    env: { ...process.env, ANTHROPIC_API_KEY: undefined, CLAUDECODE: undefined },
    mcpServers,
    ...(resume ? { resume } : {}),
    ...(policy.isOrchestrator && !useChannelDelegate ? { agents: delegationAgents(agent.id) } : {}),
  };

  let finalResult = "";
  let costUsd = 0;
  let sessionId = resume ?? "";

  try {
    for await (const msg of query({ prompt, options })) {
      const sid = (msg as any).session_id;
      if (typeof sid === "string" && sid) sessionId = sid;
      if (msg.type === "assistant") {
        const am = msg as any;
        const delegated = am.parent_tool_use_id != null;
        for (const block of am.message?.content ?? []) {
          if (block.type === "text" && block.text?.trim()) {
            await onEvent({ kind: "text", text: block.text });
          } else if (block.type === "tool_use") {
            await onEvent({
              kind: "tool",
              tool: block.name,
              summary: summarizeTool(block.name, block.input ?? {}),
              delegated,
            });
          }
        }
      } else if (msg.type === "result") {
        const r = msg as any;
        finalResult = typeof r.result === "string" ? r.result : finalResult;
        costUsd = r.total_cost_usd ?? 0;
        await onEvent({ kind: "result", text: finalResult, costUsd, turns: r.num_turns ?? 0 });
      }
    }
  } catch (e: any) {
    await onEvent({ kind: "error", message: e?.message ?? String(e) });
    throw e;
  }

  return { result: finalResult, costUsd, sessionId };
}

