export interface Bot {
  name: string; // bot key = agent name; one Discord bot per role/name
  isOrchestrator: boolean;
  agents: Agent[]; // every project-agent this bot serves (shared roles serve >1)
}

/**
 * The fleet: one bot per distinct agent name. A shared role (architect,
 * feature-dev, …) is a single bot that serves every project-agent with that
 * name; project context is resolved per channel at runtime. Bot key = name.
 */
export function getBots(): Bot[] {
  const byName = new Map<string, Bot>();
  for (const a of getRoster().flatMap((p) => p.agents)) {
    const bot = byName.get(a.name) ?? { name: a.name, isOrchestrator: false, agents: [] };
    bot.agents.push(a);
    if (a.isOrchestrator) bot.isOrchestrator = true;
    byName.set(a.name, bot);
  }
  return [...byName.values()].sort((x, y) => x.name.localeCompare(y.name));
}

/** Which project-agent (overlay) a bot should act as in a given project channel. */
export function agentForBotInProject(bot: Bot, project: string): Agent | undefined {
  return bot.agents.find((a) => a.project === project) ?? bot.agents[0];
}

