const sleep = (ms:number)=>new Promise(r=>setTimeout(r,ms));

async function dreq(method:string, path:string, body?:any): Promise<Response> {
  for (;;) {
    const r = await fetch(API+path, { method, headers:H, body: body?JSON.stringify(body):undefined });
    if (r.status===429) { const j:any = await r.json().catch(()=>({retry_after:1})); await sleep(((j.retry_after??1)*1000)+300); continue; }
