input.new_string:
  this.client.on(Events.InteractionCreate, (i) => {
    this.onInteraction(i).catch((e) => console.error(`[${this.bot.name}] interaction error:`, e));
  });
  // A transient WebSocket error (e.g. EPIPE) emits an 'error' event; if unhandled it
  // throws and crashes the whole Node process — taking every bot down with it. Swallow
  // and log: discord.js reconnects the shard automatically.
  this.client.on(Events.Error, (e) => console.error(`[${this.bot.name}] client error:`, e?.message ?? e));
  this.client.on(Events.ShardError, (e) => console.error(`[${this.bot.name}] shard error:`, e?.message ?? e));
}

