// Default entrypoint: the Discord fleet (one bot per agent). (Slack frontend: npm run start:slack)
import "dotenv/config";
import { startDiscordFleet } from "./discordApp";

// Last-resort safety net: a single unhandled error anywhere must not take the whole
// fleet (all bots) offline. Log and keep running; per-client handlers catch the rest.
process.on("uncaughtException", (e) => console.error("uncaughtException:", e?.message ?? e));
process.on("unhandledRejection", (e: any) => console.error("unhandledRejection:", e?.message ?? e));
